"""Certified Gaussian regularisation of a divergent spectral series.

Given ordinates with square-root growth t_k^2 >= k + 1, the Gaussian-windowed harmonic series
sum_k g_s(t_k) / (1/4 + t_k^2) converges even when the unwindowed series diverges.  The
convergence is quantitative: for every order n,

    (t^2)^n g_s(t) <= (s^2 / pi)^n n!      hence      g_s(t) <= C_n / (t^2)^n,

with C_n = (s^2/pi)^n n! independent of t.  Choosing the order n *after* seeing the growth
exponent gives an explicit tail bound, hence a truncation index for a prescribed accuracy.
"""

from __future__ import annotations

import math
from typing import Callable, List, Tuple


def gauss_window(s: float, t: float) -> float:
    """Gaussian window g_s(t) = exp(-pi t^2 / s^2)."""
    return math.exp(-math.pi * t * t / (s * s))


def schwartz_constant(s: float, n: int) -> float:
    """C_n = (s^2 / pi)^n n!, the constant in (t^2)^n g_s(t) <= C_n."""
    return (s * s / math.pi) ** n * math.factorial(n)


def tail_bound(s: float, n: int, k0: int) -> float:
    """Bound for sum_{k >= k0} g_s(t_k)/(1/4 + t_k^2) under t_k^2 >= k + 1.

    Uses 1/(1/4 + t_k^2) <= 4, g_s(t_k) <= C_n/(t_k^2)^n <= C_n/(k+1)^n, and the integral
    comparison sum_{k >= k0} (k+1)^{-n} <= (k0)^{-(n-1)}/(n-1) for n >= 2.
    """
    if n < 2:
        raise ValueError("the tail bound requires order n >= 2")
    if k0 < 1:
        k0 = 1
    return 4.0 * schwartz_constant(s, n) * (k0 ** (-(n - 1))) / (n - 1)


def choose_order(s: float, k0: int, target: float, max_order: int = 30) -> int:
    """Smallest order n >= 2 whose tail bound at k0 already meets the target accuracy."""
    for n in range(2, max_order + 1):
        if tail_bound(s, n, k0) <= target:
            return n
    return max_order


def truncation_index(s: float, target: float, n: int = 2, max_index: int = 10 ** 7) -> int:
    """Smallest k0 whose order-n tail bound is below the target accuracy."""
    k0 = 1
    while k0 < max_index and tail_bound(s, n, k0) > target:
        k0 *= 2
    return k0


def regularised_sum(s: float,
                    ordinate: Callable[[int], float],
                    k0: int) -> Tuple[float, float]:
    """Truncated Gaussian-windowed statistic together with its certified tail bound."""
    total = sum(gauss_window(s, ordinate(k)) / (0.25 + ordinate(k) ** 2) for k in range(k0))
    return total, tail_bound(s, 2, max(k0, 1))


def unwindowed_partial(ordinate: Callable[[int], float], k0: int) -> float:
    """Partial sum of the unwindowed statistic, for comparison."""
    return sum(1.0 / (0.25 + ordinate(k) ** 2) for k in range(k0))


if __name__ == "__main__":
    s = 1.0
    threshold_family: Callable[[int], float] = lambda k: math.sqrt(k + 1.0)

    order = choose_order(s, k0=64, target=1e-6)
    print(f"order chosen for accuracy 1e-6 beyond k = 64 : n = {order}")
    print(f"tail bound at that order                     : {tail_bound(s, order, 64):.3e}")

    for k0 in (10, 100, 1000, 10000):
        value, bound = regularised_sum(s, threshold_family, k0)
        raw = unwindowed_partial(threshold_family, k0)
        print(f"k0 = {k0:6d}:  windowed = {value:.10f}  (tail <= {bound:.2e})   "
              f"unwindowed partial = {raw:8.4f}")
    print("the unwindowed partial sums diverge logarithmically; the windowed ones do not.")
